	static long power(long a, long d, long n)
	 {
		    long res = 1; 
		    a = a % n;
		    if (a == 0)
		      return 0; 

		    while (d > 0)
		    {

		      if ((d & 1) != 0)
		        res = (res * a) % n;

		      d = d >> 1;
		      a = (a * a) % n;
		    }
		    return res;
		  }

