				int min = i+1;
				for ( int j = 0 ; j < last.length ; ++j ) {
					if ( last[j] != 0 ) min = min>last[j]?last[j]:min;
				}
				System.out.println(min+" "+(i+1)); return;
			}
		}
		System.out.println("-1 -1"); 
