	static long power(long x, long y, long p) 
    { 
        long res = 1; 
        x = x % p; 

        while (y > 0) 
        { 
            if (y % 2 == 1) 
                res = (res * x) % p; 
            y = y >> 1;
            x = (x * x) % p; 
        } 
        return  res; 
    } 
