		long num = 0, den = 1;

		void reduce() {
			long d = lib.gcd(num, den);
			num /= d;
			den /= d;
		}

		myFraction(long ch, long zn) {
			num = ch;
			den = zn;
			reduce();
		}

		myFraction add(myFraction t) {
			long nd = lib.lcm(den, t.den);
			myFraction r = new myFraction(nd / den * num + nd / t.den * t.num, nd);
			r.reduce();
			return r;
		}

