	static int[][][] f=new int[1<<16][20][20];

	static int GetBit(int x,int k)
	{
		return (x>>k)&1;
	}

	static int TurnBit(int x,int k)
	{
		return x^(1<<k);
	}

	public static void main(String[] args) 
	{
		n=in.nextInt();
		m=in.nextInt();
