		{
			res=(int)1e9;
			for(int i=1;i<m;i++)
				res=Math.min(res,Math.abs(a[0][i]-a[0][i+1]));
			out.print(res);
			out.close();
			return;
		}
		for(int i=0;i<n;i++)
			for(int j=0;j<n;j++)
			{
				Min[i][j]=Min1[i][j]=(int)1e9;
				for(int t=1;t<=m;t++)
					Min[i][j]=Math.min(Min[i][j],Math.abs(a[i][t]-a[j][t]));
				for(int t=1;t<m;t++)
					Min1[i][j]=Math.min(Min1[i][j],Math.abs(a[i][t]-a[j][t+1]));
			}
		for(int i=0;i<n;i++)
