								for(int t=0;t<n;t++)
									if(j!=t&&GetBit(mask,t)==1)
										f[mask][i][j]=Math.max(f[mask][i][j],Math.min(f[TurnBit(mask,j)][i][t],Min[j][t]));
								if(mask==(1<<n)-1)									
									res=Math.max(res,Math.min(f[mask][i][j],Min1[j][i]));
							}
		out.print(res);
		out.close();
	}
